## Instance Resolution Logic

```typescript
function resolveInstancePath(config: StoreConfig): {
  instanceId: string;
  instancePath: string;
  isNew: boolean;
} {
  const baseDir = config.baseDir ?? path.join(os.homedir(), '.multiagent');

  // In-memory: No persistence
  if (config.inMemory) {
    const instanceId = config.instanceId ?? generateInstanceId();
    return {
      instanceId,
      instancePath: ':memory:',
      isNew: true,
    };
  }

  // Explicit instance ID: Use or create
  if (config.instanceId) {
    const instancePath = path.join(baseDir, 'instances', config.instanceId);
    const isNew = !fs.existsSync(instancePath);
    return {
      instanceId: config.instanceId,
      instancePath,
      isNew,
    };
  }

  // No instance ID: Generate new
  const instanceId = generateInstanceId();
  const instancePath = path.join(baseDir, 'instances', instanceId);
  return {
    instanceId,
    instancePath,
    isNew: true,
  };
}

function generateInstanceId(): string {
  return `inst_${nanoid(12)}`;
}
```

