  options?: Record<string, unknown>;
  factory?: (instancePath: string) => StorageBackend;
}
```

### Usage Examples

```typescript
// Default: New instance with SQLite
const store = await createEventStore();

// Resume existing instance
const store = await createEventStore({
  instanceId: 'my-session',
});

// Custom backend
const store = await createEventStore({
  backend: {
    type: 'custom',
    factory: (path) => new MyCustomBackend(path),
  },
});

// Legacy path option (deprecated but works)
const store = await createEventStore({
  path: '/custom/path/store.json',
});
```

## EventStore Interface

The EventStore interface remains largely unchanged, with additions for instance metadata:

```typescript
interface EventStore {
  // ─── Instance Info (NEW) ───

  /** Get instance metadata */
  readonly instanceId: string;
  readonly namespace: string;
  readonly instancePath: string;

  /** Get backend type */
  readonly backendType: string;

  // ─── Existing API (unchanged) ───

  /** Append an event */
  appendEvent(event: Omit<Event, 'id' | 'timestamp'>): Promise<Event>;

  /** Query events */
  queryEvents(filter?: EventFilter): Promise<Event[]>;

  /** Get agent state */
  getAgent(agentId: string): Promise<AgentState | null>;

  /** Set agent state */
  setAgent(agentId: string, state: AgentState): Promise<void>;

  /** Get all agents */
  getAllAgents(): Promise<AgentState[]>;

  /** Get task state */
  getTask(taskId: string): Promise<TaskState | null>;

  /** Set task state */
  setTask(taskId: string, state: TaskState): Promise<void>;

  /** Subscribe to events */
  subscribe(
    agentId: string,
    eventType: string,
    handler: EventHandler
  ): () => void;

  /** Flush pending writes */
  flush(): Promise<void>;

  /** Close and release resources */
  close(): Promise<void>;

  // ─── New Capabilities ───

  /** Export events for peer sync */
  exportEvents(filter?: EventFilter): Promise<ExportedEvent[]>;

  /** Import events from peer */
  importEvents(events: ExportedEvent[]): Promise<void>;

  /** Get underlying backend (advanced use) */
  getBackend(): StorageBackend;
}
```

