### Example: Finding Peers

```typescript
import { discoverInstances } from 'macro-agent';

// Find all instances in my namespace
const peers = await discoverInstances('my-project');

// Find recent instances only
const activePeers = await discoverInstances('my-project', {
  maxAge: 300, // Last 5 minutes
});

// Connect to discovered peer
for (const peer of activePeers) {
  if (peer.peerEndpoint) {
    await peerManager.connect(peer.peerEndpoint);
  }
}
```

